import json
import sys
from pathlib import Path

try:
    import jsonschema
except ImportError:
    jsonschema = None


ROOT = Path(__file__).resolve().parents[1]

ARTIFACTS = {
    "chat_manifest": (
        ROOT / "manifests" / "{chat_id}.manifest.json",
        ROOT / "schemas" / "chat_manifest.schema.json",
        "MANIFEST-{chat_id}"
    ),
    "extraction_report": (
        ROOT / "artifacts" / "extraction_reports" / "{chat_id}.extraction_report.json",
        ROOT / "schemas" / "extraction_report.schema.json",
        "EXTRACTION-{chat_id}"
    ),
    "review_record": (
        ROOT / "artifacts" / "review_records" / "{chat_id}.review_record.json",
        ROOT / "schemas" / "review_record.schema.json",
        "REVIEW-{chat_id}"
    ),
    "routing_packet": (
        ROOT / "artifacts" / "routing_packets" / "{chat_id}.routing_packet.json",
        ROOT / "schemas" / "routing_packet.schema.json",
        "ROUTING-{chat_id}"
    ),
    "archive_record": (
        ROOT / "artifacts" / "archive_records" / "{chat_id}.archive_record.json",
        ROOT / "schemas" / "archive_record.schema.json",
        "ARCHIVE-{chat_id}"
    )
}


def fail(message):
    print(f"FAIL: {message}", file=sys.stderr)
    return 1


def load_json(path):
    if not path.is_file():
        raise ValueError(f"missing file: {path.relative_to(ROOT)}")
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON in {path.relative_to(ROOT)}: {exc}") from exc


def validate_schema(data, schema_path):
    schema = load_json(schema_path)
    if jsonschema is not None:
        jsonschema.Draft202012Validator(schema).validate(data)
        return
    check_minimal_schema(data, schema)


def check_minimal_schema(data, schema):
    if not isinstance(data, dict):
        raise ValueError("artifact must be a JSON object")
    allowed = set(schema.get("properties", {}))
    required = set(schema.get("required", []))
    missing = required - set(data)
    extra = set(data) - allowed
    if missing:
        raise ValueError(f"missing required fields: {sorted(missing)}")
    if schema.get("additionalProperties") is False and extra:
        raise ValueError(f"additional fields are not allowed: {sorted(extra)}")
    for field, rules in schema.get("properties", {}).items():
        if field not in data:
            continue
        if "const" in rules and data[field] != rules["const"]:
            raise ValueError(f"{field} must be {rules['const']}")
        if "enum" in rules and data[field] not in rules["enum"]:
            raise ValueError(f"{field} must be one of {rules['enum']}")


def expected_for_path(path):
    resolved = path.resolve()
    for artifact_type, (template, schema_path, expected_id) in ARTIFACTS.items():
        parent = template.parent
        suffix = template.name.replace("{chat_id}", "")
        if resolved.parent == parent and resolved.name.endswith(suffix):
            chat_id = resolved.name[:-len(suffix)]
            return artifact_type, chat_id, schema_path, expected_id.format(chat_id=chat_id)
    raise ValueError(f"unrecognized artifact path: {path}")


def validate_artifact_path(path):
    artifact_type, chat_id, schema_path, expected_id = expected_for_path(path)
    data = load_json(path)
    validate_schema(data, schema_path)
    require_common(data, artifact_type, chat_id, expected_id)
    if artifact_type == "routing_packet":
        require_route_ownership_claims(data)
    return data


def require_common(data, artifact_type, chat_id, expected_id):
    if data.get("schema_version") != "mvs-1":
        raise ValueError("schema_version must be mvs-1")
    if data.get("artifact_type") != artifact_type:
        raise ValueError(f"artifact_type must be {artifact_type}")
    if data.get("chat_id") != chat_id:
        raise ValueError(f"chat_id must be {chat_id}")
    if data.get("artifact_id") != expected_id:
        raise ValueError(f"artifact_id must be {expected_id}")


def require_route_ownership_claims(data):
    routes = data.get("routes", [])
    if not isinstance(routes, list):
        raise ValueError("routes must be an array")
    for index, route in enumerate(routes):
        if not isinstance(route, dict):
            raise ValueError(f"route entry {index} must be an object")
        if route.get("ownership_claim") != "NONE":
            raise ValueError(f"route entry {index} ownership_claim must be NONE")


def path_for(artifact_type, chat_id):
    return Path(str(ARTIFACTS[artifact_type][0]).format(chat_id=chat_id))


def validate_chain(chat_id, require_all=False):
    raw_path = ROOT / "raw_chats" / "incoming" / f"{chat_id}.raw.txt"
    if not raw_path.is_file():
        raise ValueError(f"missing raw chat: {raw_path.relative_to(ROOT)}")
    if raw_path.stat().st_size == 0:
        raise ValueError(f"empty raw chat: {raw_path.relative_to(ROOT)}")

    present = {}
    for artifact_type in ARTIFACTS:
        path = path_for(artifact_type, chat_id)
        if path.exists():
            present[artifact_type] = validate_artifact_path(path)
        elif require_all:
            raise ValueError(f"missing file: {path.relative_to(ROOT)}")

    if "chat_manifest" not in present:
        raise ValueError(f"missing file: {path_for('chat_manifest', chat_id).relative_to(ROOT)}")

    manifest_id = f"MANIFEST-{chat_id}"
    extraction_id = f"EXTRACTION-{chat_id}"
    review_id = f"REVIEW-{chat_id}"
    routing_id = f"ROUTING-{chat_id}"

    manifest = present["chat_manifest"]
    if manifest.get("raw_chat_path") != f"raw_chats/incoming/{chat_id}.raw.txt":
        raise ValueError("manifest raw_chat_path mismatch")

    if "extraction_report" in present:
        if present["extraction_report"].get("manifest_id") != manifest_id:
            raise ValueError("extraction manifest_id mismatch")

    if "review_record" in present:
        review = present["review_record"]
        if "extraction_report" not in present:
            raise ValueError("review exists without extraction report")
        if review.get("extraction_report_id") != extraction_id:
            raise ValueError("review extraction_report_id mismatch")

    if "routing_packet" in present:
        routing = present["routing_packet"]
        review = present.get("review_record")
        if review is None:
            raise ValueError("routing exists without review record")
        if review.get("review_status") != "APPROVED":
            raise ValueError("routing exists without approved review")
        if routing.get("extraction_report_id") != extraction_id:
            raise ValueError("routing extraction_report_id mismatch")
        if routing.get("review_record_id") != review_id:
            raise ValueError("routing review_record_id mismatch")

    if "archive_record" in present:
        archive = present["archive_record"]
        if "routing_packet" not in present:
            raise ValueError("archive exists without routing packet")
        if archive.get("manifest_id") != manifest_id:
            raise ValueError("archive manifest_id mismatch")
        if archive.get("extraction_report_id") != extraction_id:
            raise ValueError("archive extraction_report_id mismatch")
        if archive.get("review_record_id") != review_id:
            raise ValueError("archive review_record_id mismatch")
        if archive.get("routing_packet_id") != routing_id:
            raise ValueError("archive routing_packet_id mismatch")

    return present


def main():
    if len(sys.argv) < 3:
        return fail("usage: python scripts/validate_artifact.py artifact <artifact_path> | chain CHAT-000001")

    try:
        if sys.argv[1] == "artifact" and len(sys.argv) == 3:
            validate_artifact_path((ROOT / sys.argv[2]).resolve() if not Path(sys.argv[2]).is_absolute() else Path(sys.argv[2]))
        elif sys.argv[1] == "chain" and len(sys.argv) == 3:
            validate_chain(sys.argv[2])
        else:
            return fail("usage: python scripts/validate_artifact.py artifact <artifact_path> | chain CHAT-000001")
    except Exception as exc:
        return fail(str(exc))

    print("PASS")
    return 0


if __name__ == "__main__":
    sys.exit(main())
