import json
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def fail(message):
    print(f"FAIL: {message}", file=sys.stderr)
    return 1


def main():
    if len(sys.argv) != 3:
        return fail('usage: python scripts/register_chat.py CHAT-000001 "ChatGPT Recents"')

    chat_id = sys.argv[1]
    source_label = sys.argv[2]
    raw_path = ROOT / "raw_chats" / "incoming" / f"{chat_id}.raw.txt"
    manifest_path = ROOT / "manifests" / f"{chat_id}.manifest.json"

    if not raw_path.is_file():
        return fail(f"missing raw chat: {raw_path.relative_to(ROOT)}")
    if raw_path.stat().st_size == 0:
        return fail(f"empty raw chat: {raw_path.relative_to(ROOT)}")
    if manifest_path.exists():
        return fail(f"manifest already exists: {manifest_path.relative_to(ROOT)}")

    manifest = {
        "schema_version": "mvs-1",
        "artifact_id": f"MANIFEST-{chat_id}",
        "artifact_type": "chat_manifest",
        "chat_id": chat_id,
        "source_label": source_label,
        "raw_chat_path": f"raw_chats/incoming/{chat_id}.raw.txt",
        "lifecycle_state": "REGISTERED",
        "ownership_claim": "NONE"
    }

    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(f"PASS: created {manifest_path.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
